-- Blank-field counts across active staff. Columns: active, no_dss, no_dob, no_email, no_nat, no_lic, no_id, no_sal, no_gosi, no_prob
SELECT COUNT(*) ACTIVE, SUM(CASE WHEN m.DATE_START_SERVICE IS NULL THEN 1 ELSE 0 END) NO_DSS, SUM(CASE WHEN m.DATE_OF_BIRTH IS NULL THEN 1 ELSE 0 END) NO_DOB, SUM(CASE WHEN m.EMAIL IS NULL THEN 1 ELSE 0 END) NO_EMAIL, SUM(CASE WHEN m.NATIONALITY_CODE IS NULL THEN 1 ELSE 0 END) NO_NAT, SUM(CASE WHEN m.LICENSE_ID IS NULL THEN 1 ELSE 0 END) NO_LIC, SUM(CASE WHEN NOT EXISTS (SELECT 1 FROM {P}PS_STAFF_IDS i WHERE i.STAFF_ID=c.STAFF_ID AND i.ID_NO IS NOT NULL) THEN 1 ELSE 0 END) NO_ID, SUM(CASE WHEN NOT EXISTS (SELECT 1 FROM {P}PR_STAFF_DEFAULT_SALARY_M s WHERE s.STAFF_ID=c.STAFF_ID AND s.DATE_END IS NULL) THEN 1 ELSE 0 END) NO_SAL, SUM(CASE WHEN c.GOSI_DATE IS NULL THEN 1 ELSE 0 END) NO_GOSI, SUM(CASE WHEN c.TEST_PERIOD_DAYS IS NULL THEN 1 ELSE 0 END) NO_PROB FROM {P}PS_STAFF_CONTRACT c JOIN {P}STAFF_MASTER m ON m.STAFF_ID=c.STAFF_ID WHERE c.STATUS='A' AND c.CURRENT_CONTRACT='Y'
